#include <bits/stdc++.h>
using namespace std;using I=long long;using G=vector<int>;using P=array<I,7>;
void need(bool q,string s){if(!q)throw runtime_error(s);}
void valid(G a){int n=a.size();for(int i=0;i<n;i++){need(a[i]>=0&&a[i]<(1<<n)&&!(a[i]>>i&1),"row");for(int j=0;j<i;j++)need(((a[i]>>j&1)+(a[j]>>i&1))==1,"pair");}}
P count(G a,int root=0){valid(a);int n=a.size(),N=1<<n,F=N-1;vector<I>en(N*n),st(N*n),H(N);H[0]=1;for(int i=0;i<n;i++)en[(1<<i)*n+i]=st[(1<<i)*n+i]=1;for(int S=1;S<N;S++)for(int v=0;v<n;v++)if(S>>v&1){int A=S^(1<<v);for(int w=0;w<n;w++)if(A>>w&1){if(a[w]>>v&1)en[S*n+v]+=en[A*n+w];else st[S*n+v]+=st[A*n+w];}H[S]+=en[S*n+v];}I L=0,R=0,b=0;for(int S=0;S<N;S++){L+=en[S*n+root]*H[F^S];R+=st[S*n+root]*H[F^S];}int D=F^(1<<root),A=D;while(true){b+=H[A]*H[D^A];if(!A)break;A=(A-1)&D;}return {H[F],st[F*n+root],en[F*n+root],L,R,H[D],b};}
G relabel(G a,int root){vector<int>ord{root};for(int i=0;i<(int)a.size();i++)if(i!=root)ord.push_back(i);G b(a.size());for(int i=0;i<(int)a.size();i++)for(int j=0;j<(int)a.size();j++)if(a[ord[i]]>>ord[j]&1)b[i]|=1<<j;return b;}
G move(G a,char op){int n=a.size();for(auto&x:a)x|=1<<n;a.push_back(0);if(op!='O'){a[0]^=1<<n;a[n]=1;}if(op=='J')a=relabel(a,n);return a;}
P trans(P p,char op){auto[h,s,e,L,R,d,b]=p;if(op=='O')return {h,s,0,L,2*R,d,2*b};need(op=='Z',"unsupported transfer");return{h+R-e,s,d,L+b,2*R-d,d,2*b};}
I X(P p,int j){return p[0]+p[3]-p[1]+2*j;}
array<I,4> row(P p,int j){return {X(p,j),p[2],p[4]+p[6],p[5]};}
bool strong(G a){int n=a.size(),F=(1<<n)-1;for(int v=0;v<n;v++)a[v]|=1<<v;for(int k=0;k<n;k++)for(int v=0;v<n;v++)if(a[v]>>k&1)a[v]|=a[k];return all_of(a.begin(),a.end(),[&](int x){return x==F;});}
string canonroot(G a){int n=a.size();map<pair<int,int>,vector<int>>cells;for(int i=1;i<n;i++)cells[{__builtin_popcount((unsigned)a[i]),(a[0]>>i)&1}].push_back(i);vector<vector<int>>parts;for(auto&[d,p]:cells)parts.push_back(p);vector<int>ord{0};string best(n*(n-1)/2,'2');function<void(int)>rec=[&](int g){if(g==(int)parts.size()){string code;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)code+=char('0'+((a[ord[i]]>>ord[j])&1));best=min(best,code);return;}auto p=parts[g];do{for(int v:p)ord.push_back(v);rec(g+1);ord.resize(ord.size()-p.size());}while(next_permutation(p.begin(),p.end()));};rec(0);return best;}
G decroot(string code,int n){G a(n);int b=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++,b++)if(code[b]=='1')a[i]|=1<<j;else a[j]|=1<<i;return a;}
struct Forms{int n,m;vector<I> en,st,C,root,RC;};
Forms forms(G u){int n=u.size();G a=u;a[0]|=1<<n;a.push_back(((1<<n)-1)^1);int m=n+1,N=1<<m,F=N-1,U=(1<<n)-1;vector<I>en(N*m),st(N*m),C(m*m),root((1<<n)*n),RC(n*n);for(int i=0;i<m;i++)en[(1<<i)*m+i]=st[(1<<i)*m+i]=1;for(int S=1;S<N;S++)for(int v=0;v<m;v++)if(S>>v&1){int rem=S^(1<<v);for(int w=0;w<m;w++)if(rem>>w&1){if(a[w]>>v&1)en[S*m+v]+=en[rem*m+w];else st[S*m+v]+=st[rem*m+w];}}
 for(int S=1;S<F;S++)for(int i=0;i<m;i++)if(en[S*m+i])for(int j=0;j<m;j++)if(st[(F^S)*m+j])C[i*m+j]+=en[S*m+i]*st[(F^S)*m+j];
 root[1*n]=1;for(int S=1;S<=U;S+=2)for(int v=0;v<n;v++)if(root[S*n+v])for(int w=0;w<n;w++)if(!(S>>w&1)&&(u[v]>>w&1))root[(S|1<<w)*n+w]+=root[S*n+v];
 for(int S=1;S<U;S+=2)for(int i=0;i<n;i++)if(root[S*n+i])for(int j=0;j<n;j++)if(st[(U^S)*m+j])RC[i*n+j]+=root[S*n+i]*st[(U^S)*m+j];
 vector<I>ends(m),starts(m),roots(n);for(int i=0;i<m;i++){ends[i]=en[F*m+i];starts[i]=st[F*m+i];}for(int i=0;i<n;i++)roots[i]=root[U*n+i];return {n,m,ends,starts,C,roots,RC};}
array<I,2> childcounts(const Forms&f,int mask){int n=f.n,m=f.m;I B=0,s=0;int in=mask|(1<<n),out=((1<<n)-1)^mask;for(int i=0;i<m;i++){if(in>>i&1)B+=f.en[i];else B+=f.st[i];}for(int i=0;i<m;i++)if(in>>i&1)for(int j=0;j<m;j++)if(out>>j&1)B+=f.C[i*m+j];for(int i=0;i<n;i++)if(mask>>i&1){s+=f.root[i];for(int j=0;j<n;j++)if(out>>j&1)s+=f.RC[i*n+j];}return {B,s};}
int main(int argc,char**argv){int bound=argc>1?stoi(argv[1]):137,cap=argc>2?stoi(argv[2]):26;need(bound>=5&&bound<=2001&&cap>=1,"bounds");int ncap=2;for(int n=3;;n++){I val;if(n%3==0){val=3;for(int k=0;k<(n-3)/3;k++)val*=5;}else if(n%3==1){val=1;for(int k=0;k<(n-1)/3;k++)val*=5;}else{val=9;for(int k=0;k<(n-5)/3;k++)val*=5;}if(val>bound)break;ncap=n-1;}
 vector<map<string,array<I,2>>>bank(ncap+1);G tri{2,4,1};bank[3][canonroot(tri)]={5,1};set<pair<I,I>>profiles;ofstream file("ROOTED_BANK.tsv");vector<I>trials(ncap+1),accepted(ncap+1);int litchecks=0;
 for(int n=3;n<=ncap;n++){if(n>3){for(auto&[code,ps]:bank[n-1]){G a=decroot(code,n-1);auto ff=forms(a);for(int mask=1;mask<(1<<(n-1))-1;mask++){trials[n]++;auto cp=childcounts(ff,mask);need(cp[0]>=ps[0]&&cp[1]>=ps[1],"monotone profile");if(cp[0]>bound||cp[1]>cap)continue;accepted[n]++;G b=a;for(int i=0;i<n-1;i++)if(mask>>i&1)b[i]|=1<<(n-1);b.push_back(((1<<(n-1))-1)^mask);string key=canonroot(b);auto[it,ok]=bank[n].emplace(key,cp);need(ok||it->second==cp,"root canonical collision");}}}
 cerr<<"n="<<n<<" trials="<<trials[n]<<" accepted="<<accepted[n]<<" classes="<<bank[n].size()<<'\n';for(auto&[code,ps]:bank[n]){G a=decroot(code,n);profiles.insert({ps[0],ps[1]});file<<n<<' '<<ps[0]<<' '<<ps[1];for(int row:a)file<<' '<<row;file<<'\n';if(bound<=137){P p=count(a);need(X(p,0)==ps[0]&&p[1]==ps[1]&&strong(a),"independent direct source check");litchecks++;}}}
 ofstream pfile("ROOTED_PROFILES.tsv");for(auto[B,s]:profiles)pfile<<B<<' '<<s<<'\n';cout<<"{\n \"status\": \"COMPLETE_ROOTED_STRONG_GENERATION\",\n \"B_bound\": "<<bound<<",\n \"s_cap\": "<<cap<<",\n \"source_order_cap\": "<<ncap<<",\n \"classes_by_order\": {";for(int n=3;n<=ncap;n++){if(n>3)cout<<", ";cout<<'"'<<n<<"\": "<<bank[n].size();}cout<<"},\n \"strong_profile_count\": "<<profiles.size()<<",\n \"literal_recounts\": "<<litchecks<<",\n \"all_base_F\": \"OPEN\"\n}\n";
}
